} else {
  var enc = '';
  try {
    var bytes = new Packages.java.lang.String(String(key)).getBytes('GBK');
    for (var i = 0; i < bytes.length; i++) {
      var b = bytes[i] & 0xff;
      if ((b >= 48 && b <= 57) || (b >= 65 && b <= 90) || (b >= 97 && b <= 122)) {
        enc += String.fromCharCode(b);
      } else {
        enc += '%' + (b < 16 ? '0' : '') + b.toString(16).toUpperCase();
      }
    }
  } catch(e) {
    java.log('GBK_ENC_ERR:' + e);
  }
  var body = 's=' + enc + '&type=articlename';
  out = U + '/s.php,' + JSON.stringify({method:'POST', body:body, headers:{'Content-Type':'application/x-www-form-urlencoded','Accept-Encoding':'identity','Referer':U + '/','Origin':U}});
}
